AWS CloudFront & Amazon S3.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(aws_cloudfront_amazon_s3, "AWS CloudFront & Amazon S3") {
    Component(CloudFront_Distribution, "CloudFront Distribution", "AWS CloudFront", "Provides global content delivery and edge caching for static assets.")
    Component(Amazon_S3_Bucket, "Amazon S3 Bucket", "Amazon S3", "Stores static assets for the Single Page Application.")
}

Rel(CloudFront_Distribution, Amazon_S3_Bucket, "Fetches static assets via HTTPS [IAM OAC]", "HTTPS")

@enduml

AWS API Gateway.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(aws_api_gateway, "AWS API Gateway") {
    Component(Authorizer, "Authorizer", "Amazon API Gateway v2/HTTP API Authorizer", "Validates OAuth2/JWT tokens for incoming requests.")
    Component(Throttling, "Throttling", "Amazon API Gateway Rate-Limiting", "Manages rate-limiting and protects backend services from high traffic loads.")
    Component(Routing, "Routing", "Amazon API Gateway HTTP API Routing", "Routes incoming HTTPS REST/JSON and gRPC-Web requests to backend ECS/Fargate microservices via AWS VPC Link.")
}

Rel(Authorizer, Throttling, "Passes authenticated requests to")
Rel(Throttling, Routing, "Forwards rate-limited requests to")

@enduml

User & Compliance Service.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(user_compliance_service, "User & Compliance Service") {
    Component(profile_controller, "Profile Controller", "Spring MVC / Express.js", "Manages user profiles and authentication requests.")
    Component(compliance_manager, "Compliance Manager", "Spring Boot / Node.js", "Handles GDPR/CCPA data compliance workflows.")
    Component(audit_logger, "Audit Logger", "Spring Data JPA / TypeORM", "Persists immutable audit logs for compliance tracking.")
    Component(erasure_event_publisher, "Erasure Event Publisher", "AWS SDK", "Publishes UserDeletedEvent for asynchronous event-driven data erasure.")
}

Rel(profile_controller, compliance_manager, "Delegates compliance requests")
Rel(compliance_manager, audit_logger, "Records audit logs")
Rel(compliance_manager, erasure_event_publisher, "Triggers data erasure events")

@enduml

Amazon RDS PostgreSQL.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Amazon RDS PostgreSQL container

Container_Boundary(rds_postgresql, "Amazon RDS PostgreSQL") {
    Component(Primary Database Instance, "Primary Database Instance", "PostgreSQL", "Handles write operations and ensures transactional integrity for orders and user data.")
    Component(Read Replicas, "Read Replicas", "PostgreSQL Read Replicas", "Handles read-heavy workloads such as catalog browsing and reviews to reduce load on the primary database.")
}

Rel(Primary Database Instance, Read Replicas, "Replicates transactional data", "PostgreSQL Replication")

@enduml
